#!/usr/bin/env bash
# ==========================================================================
# setapi.sh — bootstrap all per-app .env.local files with the real dev
# credentials, in one shot, after a fresh clone.
#
#   ⚠️  THIS FILE CONTAINS SECRETS. It is gitignored (see .gitignore).
#       NEVER commit it, never push it to GitHub, never paste it anywhere.
#
# Usage (from repo root):   bash setapi.sh    (or: chmod +x setapi.sh && ./setapi.sh)
#
# It OVERWRITES the three .env.local files with the values below. Edit the
# values here (not the generated files) so this stays the single source.
# For PRODUCTION: rotate every secret, set COOKIE_SECURE=true, use real
# domains in CORS_ORIGINS / NEXT_PUBLIC_* , and a strong ADMIN_PASSWORD.
# ==========================================================================
set -euo pipefail
cd "$(dirname "$0")"

