PORT=4000
# MongoDB Atlas. Password had an "@" so it's URL-encoded (@ -> %40).
# Offline fallback: MONGODB_URI=mongodb://127.0.0.1:27017/rangamai
MONGODB_URI=mongodb+srv://anger:Radha%40123@rangamdbfree.xhhxr3g.mongodb.net/rangamai?retryWrites=true&w=majority&appName=rangamDBFREE

# Auth
JWT_SECRET=u2Jbvduws--NBu_8HvdduaLa42f3ywYT35k23vJG53LucG_0k_VuLGbt2BsP_g7h
JWT_EXPIRES_IN=1d
COOKIE_SECURE=false
COOKIE_NAME=rangamai_token

# CORS — public site + admin dashboard
CORS_ORIGINS=http://localhost:3000,http://localhost:3001

# Seed admin (change the password before any real deployment)
ADMIN_EMAIL=admin@rangamai.in
ADMIN_PASSWORD=ChangeMe!Dev12345
ADMIN_NAME=RANGAMAI Admin

# Cloudinary (real keys — gitignored, never commit)
CLOUDINARY_CLOUD_NAME=lukaemhr
CLOUDINARY_API_KEY=538597584168569
CLOUDINARY_API_SECRET=mE8cIbyUkWfByCmUjV8ItI7oEpo
CLOUDINARY_FOLDER=rangamai
EOF

# ---------------------------------------------------------------- apps/web
cat > apps/web/.env.local <<'EOF'
# RANGAMAI public site — local dev. Gitignored. Generated by setapi.sh.
NEXT_PUBLIC_SITE_URL=http://localhost:3000
NEXT_PUBLIC_API_URL=http://localhost:4000
EOF

# -------------------------------------------------------------- apps/admin
cat > apps/admin/.env.local <<'EOF'
# RANGAMAI admin dashboard — local dev. Gitignored. Generated by setapi.sh.
NEXT_PUBLIC_API_URL=http://localhost:4000
